values ('relate|canal', 'relate', 'relate-4-0-bte-earmold-order', 'bte', 'canal', 'Canal (CU)', '[{"id":"acrylic","label":"Acrylic (AC)","colors":[{"id":"clear-21-standard","label":"Clear (21) — standard"},{"id":"translucent-pink-t-","label":"Translucent Pink (T)"},{"id":"translucent-brown-n-","label":"Translucent Brown (N)"}]},{"id":"silicone-s70","label":"Silicone (S70)","colors":[{"id":"clear-21-standard","label":"Clear (21) — standard"},{"id":"translucent-pink-t-","label":"Translucent Pink (T)"},{"id":"translucent-brown-n-","label":"Translucent Brown (N)"},{"id":"black-06-","label":"Black (06)"},{"id":"blue-07-","label":"Blue (07)"},{"id":"purple-08-","label":"Purple (08)"},{"id":"red-10-","label":"Red (10)"},{"id":"orange-11-","label":"Orange (11)"},{"id":"green-17-","label":"Green (17)"},{"id":"white-19-","label":"White (19)"},{"id":"yellow-20-","label":"Yellow (20)"},{"id":"flamingo-pink-5b-","label":"Flamingo Pink (5B)"},{"id":"jungle-green-2b-","label":"Jungle Green (2B)"},{"id":"galactic-blue-metallic-1b-","label":"Galactic Blue Metallic (1B)"},{"id":"star-dust-silver-metallic-3b-","label":"Star Dust Silver Metallic (3B)"},{"id":"magic-pink-metallic-4b-","label":"Magic Pink Metallic (4B)"}],"notes":"Specialty/metallic colors silicone only; not available on SlimTip soft solid"}]'::jsonb, '[{"id":"aov","label":"AOV Acoustically Optimized (audiogram required)"},{"id":"vari-pressure","label":"Vari-Vent Pressure 1.2 mm (S12)"},{"id":"vari-small","label":"Vari-Vent Small 2.0 mm (S20)"},{"id":"vari-medium","label":"Vari-Vent Medium 2.5 mm (S25)"},{"id":"vari-large","label":"Vari-Vent Large 3.0 mm (S30)"},{"id":"parallel","label":"Parallel (circular) 1.2 mm"},{"id":"styled-custom","label":"Styled/Custom large (3L)"},{"id":"iros-a","label":"IROS A / Semi-IROS / 3.0 mm"},{"id":"iros-b","label":"IROS B / Full-IROS / 3.0 mm"},{"id":"none","label":"No vent (X)"}]'::jsonb, '{}'::jsonb, '{"options":["13 Regular (13M — standard for acrylic)","13 Thick wall (13T — standard for silicone)","13 Dry wall (13D)","Slim tube length 00-3 (SlimTips only)"]}'::jsonb, '{"finish":["Gloss (standard)","No Lacquer (acrylic Clear-21/Pink-26/Cocoa-22 only)"],"options":["Removal filament (RF)","Canal lock (CL — matches shell color)"]}'::jsonb, 'UHCH-exclusive private label (Unitron-built).', 106, 'high')
on conflict (id) do update set
  manufacturer = excluded.manufacturer, form_id = excluded.form_id,
  device_type = excluded.device_type, style_id = excluded.style_id,
  style_label = excluded.style_label, materials = excluded.materials,
  vents = excluded.vents, canal = excluded.canal, tubing = excluded.tubing,
  extras = excluded.extras, constraints_note = excluded.constraints_note,
  sort_order = excluded.sort_order, confidence = excluded.confidence,
  updated_at = now();

